export function findStatisticalDistributionsById(id: string): StatisticalDistributionRecord | undefined {
  return STATISTICAL_DISTRIBUTIONS_DATABASE.find(item => item.id === id);
}

export function getAllStatisticalDistributionsRecords(): StatisticalDistributionRecord[] {
  return STATISTICAL_DISTRIBUTIONS_DATABASE;
}

export function filterStatisticalDistributionsByPredicate(predicate: (item: StatisticalDistributionRecord) => boolean): StatisticalDistributionRecord[] {
  return STATISTICAL_DISTRIBUTIONS_DATABASE.filter(predicate);
}

export function countStatisticalDistributionsRecords(): number {
  return STATISTICAL_DISTRIBUTIONS_DATABASE.length;
}
